mod io;use quantum_ecc::circuit::{Op,OperationType as K};use std::collections::{BTreeMap,HashMap,HashSet};use serde_json::{Value,json};
fn idle_through(touches:&[usize],after:usize,until:usize)->bool{let at=touches.partition_point(|&i|i<=after);touches.get(at).is_none_or(|&i|i>until)}
fn term_cost(v:&Value)->usize{v["terms"].as_array().unwrap().iter().filter(|t|t["kind"].as_u64()==Some(K::CCX as u64)).count()*2}
fn term_proxy(v:&Value,weights:&HashMap<usize,f64>)->f64{v["terms"].as_array().unwrap().iter().filter(|t|t["kind"].as_u64()==Some(K::CCX as u64)).map(|t|{let at=t["producer"].as_u64().unwrap()as usize;2.*if t["guard_expression"].as_u64()==Some(1){1.}else{weights[&at]}}).sum()}
fn merge(plan:&Value,touches:&[Vec<usize>],weights:&HashMap<usize,f64>)->Value{
 let mut active=BTreeMap::<String,(usize,usize,Value)>::new();let mut intervals=vec![];let(mut raw_cost,mut raw_proxy,mut merges)=(0usize,0f64,0usize);
 let mut close=|lo:usize,hi:usize,v:Value|{intervals.push(json!({"lo":lo,"hi":hi,"extra_toffoli_records_upper_bound":term_cost(&v),"victim":v}));};
 for row in plan["regions"].as_array().unwrap(){let(lo,hi)=(row["lo"].as_u64().unwrap()as usize,row["hi"].as_u64().unwrap()as usize);let mut current=BTreeMap::new();if let Some(victims)=row["victims"].as_array(){for v in victims{let key=serde_json::to_string(v).unwrap();assert!(current.insert(key,v.clone()).is_none());raw_cost+=term_cost(v);raw_proxy+=term_proxy(v,weights);}}
  let old=std::mem::take(&mut active);for(key,(start,previous_hi,v))in old{let wire=v["wire"].as_u64().unwrap()as usize;if current.remove(&key).is_some(){if idle_through(&touches[wire],previous_hi,hi){active.insert(key,(start,hi,v));merges+=1;}else{close(start,previous_hi,v.clone());active.insert(key,(lo,hi,v));}}else{close(start,previous_hi,v);}}
  for(key,v)in current{active.insert(key,(lo,hi,v));}
 }
 for(_, (lo,hi,v))in active{close(lo,hi,v);}drop(close);intervals.sort_by_key(|v|(v["lo"].as_u64().unwrap(),v["victim"]["wire"].as_u64().unwrap()));let merged_cost:usize=intervals.iter().map(|r|term_cost(&r["victim"])).sum();let merged_proxy:f64=intervals.iter().map(|r|term_proxy(&r["victim"],weights)).sum();assert!(merged_cost<=raw_cost);let complete=plan["all_regions_covered"].as_bool().unwrap();
 json!({"target_cap":plan["target_cap"],"all_regions_covered":complete,"unproved_regions":plan["unproved_regions"],"original_regions":plan["regions"].as_array().unwrap().len(),"joined_adjacent_victim_loans":merges,"merged_victim_intervals":intervals.len(),"original_component_added_ccx_records":raw_cost,"merged_component_added_ccx_records":merged_cost,"complete_plan_extra_executed_toffoli_per_shot_upper_bound":if complete{Some(merged_cost)}else{None},"original_component_depth_weight_proxy":raw_proxy,"merged_component_depth_weight_proxy":merged_proxy,"intervals":intervals,"scope":"Merge ONLY identical full victim/term keys in consecutive plan rows, with every original quantum touch absent across the entire extended interval. Original selected victim sets are independent in each region, so overlapping merged loans remain independent at uncompute/restore events. Global original lifetime pressure between regions is at most cap. This is an exact source-bound plan transformation, not an emitted allocator or achieved resource. Depth weights are diagnostic; incomplete plans have no complete bound."})
}
fn main(){let a:Vec<_>=std::env::args().collect();assert_eq!(a.len(),4);let ops=io::load_ops(&a[1]);let grid:Value=serde_json::from_slice(&std::fs::read(&a[2]).unwrap()).unwrap();let nq=quantum_ecc::circuit::analyze_ops(ops.iter()).0 as usize;let mut touches=vec![vec![];nq];let mut weights=HashMap::new();let mut depth=0i32;for(i,o)in ops.iter().enumerate(){match o.kind{K::PushCondition=>{depth+=1;continue;},K::PopCondition=>{depth-=1;assert!(depth>=0);continue;},_=>{}}if o.kind==K::CCX{weights.insert(i,2f64.powi(-depth-i32::from(o.c_condition.0!=u64::MAX)));}if !matches!(o.kind,K::AppendToRegister|K::Register){let mut wires:Vec<_>=[o.q_control2.0,o.q_control1.0,o.q_target.0].into_iter().filter(|&q|q!=u64::MAX).collect();wires.sort_unstable();wires.dedup();for q in wires{touches[q as usize].push(i);}}}assert_eq!(depth,0);let mut results=vec![];for row in grid["plans"].as_array().unwrap(){let path=row["path"].as_str().unwrap();let plan:Value=serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();let result=merge(&plan,&touches,&weights);let cap=result["target_cap"].as_u64().unwrap();let out=format!("{}/cap{cap}-MERGED.json",a[3]);std::fs::write(&out,serde_json::to_string_pretty(&result).unwrap()+"\n").unwrap();results.push(json!({"cap":cap,"covered":result["all_regions_covered"],"unproved_regions":result["unproved_regions"],"joined_adjacent_loans":result["joined_adjacent_victim_loans"],"raw_component_ccx_records":result["original_component_added_ccx_records"],"merged_component_ccx_records":result["merged_component_added_ccx_records"],"complete_extra_T_upper_bound":result["complete_plan_extra_executed_toffoli_per_shot_upper_bound"],"component_depth_proxy":result["merged_component_depth_weight_proxy"]}));}
 std::fs::write(format!("{}/RESULT.json",a[3]),serde_json::to_string_pretty(&json!({"status":"SOURCE_BOUND_ADJACENT_LOAN_MERGE_COMPLETE_NOT_ACHIEVED_RESOURCES","cases":results,"scope":"No point inputs, census, gate, nonce or quantum resource score. Only source-derived plan rows and complete original wire-touch ledger."})).unwrap()+"\n").unwrap();println!("MERGED_PLAN_GRID_COMPLETE");}
#[cfg(test)]mod tests{use super::*;
 fn victim()->Value{json!({"wire":1,"terms":[{"kind":13,"producer":0,"guard_expression":1}]})}
 #[test]fn identical_idle_loans_merge_but_a_quantum_phase_touch_splits_them(){let v=victim();let p=json!({"target_cap":2,"all_regions_covered":true,"unproved_regions":0,"regions":[{"lo":2,"hi":3,"victims":[v.clone()]},{"lo":7,"hi":9,"victims":[v]}]});let weights=HashMap::from([(0,1.)]);let r=merge(&p,&[vec![],vec![0,10]],&weights);assert_eq!(r["complete_plan_extra_executed_toffoli_per_shot_upper_bound"],2);assert_eq!(r["joined_adjacent_victim_loans"],1);let r=merge(&p,&[vec![],vec![0,5,10]],&weights);assert_eq!(r["complete_plan_extra_executed_toffoli_per_shot_upper_bound"],4);assert_eq!(r["joined_adjacent_victim_loans"],0);}
 #[test]fn failed_region_breaks_merging_and_never_acquires_a_complete_bound(){let v=victim();let p=json!({"target_cap":2,"all_regions_covered":false,"unproved_regions":1,"regions":[{"lo":2,"hi":3,"victims":[v.clone()]},{"lo":4,"hi":5,"status":"UNPROVED"},{"lo":7,"hi":9,"victims":[v]}]});let r=merge(&p,&[vec![],vec![0,10]],&HashMap::from([(0,1.)]));assert!(r["complete_plan_extra_executed_toffoli_per_shot_upper_bound"].is_null());assert_eq!(r["merged_component_added_ccx_records"],4);}
}
